<template><div class="page"><el-card><template #header><div><h2>AI 设置</h2><span class="muted">用于生成符合场景字段和业务语义的测试数据</span></div></template><el-form :model="form" label-position="top" class="settings-form"><div class="config-grid"><el-form-item label="供应商"><el-input v-model="form.provider"/></el-form-item><el-form-item label="模型"><el-input v-model="form.model"/></el-form-item></div><el-form-item label="Base URL"><el-input v-model="form.baseUrl"/></el-form-item><el-form-item label="API Key"><el-input v-model="form.apiKey" type="password" show-password :placeholder="current.apiKeyMasked||'输入 API Key'"/></el-form-item><el-switch v-model="form.enabled" active-text="启用 AI 数据生成"/><div class="form-actions"><el-button type="primary" @click="save">保存设置</el-button><el-button @click="testConnection">测试连接</el-button></div></el-form></el-card></div></template>
<script setup>import{onMounted,reactive,ref}from'vue';import{ElMessage}from'element-plus';import{api}from'../api';const current=ref({}),form=reactive({provider:'openai',model:'gpt-4.1-mini',baseUrl:'',apiKey:'',enabled:true});onMounted(async()=>{current.value=await api('/api/settings/llm');Object.assign(form,{...current.value,apiKey:''})});async function save(){current.value=await api('/api/settings/llm',{method:'PUT',body:JSON.stringify(form)});form.apiKey='';ElMessage.success('AI 设置已保存')}async function testConnection(){const r=await api('/api/settings/llm/test',{method:'POST',body:'{}'});ElMessage.success(r.message)}</script>
